void BOARD_BootClockXTAL32M(void)
{
    /*!< Set up the clock sources */
    /*!< Configure FRO192M */
    POWER_PeripheralPowerOn(kPOWERCFG_FRO192M);          /*!< Ensure FRO is on  */
    CLOCK_SetupFROClocking(12000000U);                   /*!< Set up FRO to the 12 MHz, just for sure */
    CLOCK_AttachClk(kFRO12M_to_MAIN_CLK);                /*!< Switch to FRO 12MHz first to ensure we can change the clock setting */

    ANACTRL->FRO192M_CTRL &= ~ANACTRL_FRO192M_CTRL_ENA_48MHZCLK_MASK;    /* Disable FRO 48 MHz output */
    ANACTRL->FRO192M_CTRL &= ~ANACTRL_FRO192M_CTRL_ENA_32MHZCLK_MASK;    /* Disable FRO HF(32MHz) output */
    ANACTRL->FRO192M_CTRL &= ~ANACTRL_FRO192M_CTRL_ENA_24MHZCLK_MASK;    /* Disable FRO FRO 24MHz output */
    ANACTRL->FRO192M_CTRL &= ~ANACTRL_FRO192M_CTRL_ENA_64MHZCLK_MASK;    /* Disable FRO 64MHz output */

    /*!< Configure XTAL32M */
    CLOCK_SetupExtClocking(32000000U);                    /* Enable clk_in clock */

    CLOCK_SetFLASHAccessCyclesForFreq(32000000U);          /*!< Set FLASH wait states for core */

    /*!< Set up dividers */
    CLOCK_SetClkDiv(kCLOCK_DivAhbClk, 1U, false);         /*!< Set AHBCLKDIV divider to value 1 */

    /*!< Set up clock selectors - Attach clocks to the peripheries */
    CLOCK_AttachClk(kEXT_CLK_to_MAIN_CLK);                 /*!< Switch MAIN_CLK to EXT_CLK */

    /*!< Set SystemCoreClock variable. */
    SystemCoreClock = BOARD_BOOTCLOCKXTAL32M_CORE_CLOCK;

    /*!< Disable FRO192M to save power */
    POWER_PeripheralPowerOff(kPOWERCFG_FRO192M);
}

/*******************************************************************************
 * Variables for BOARD_Configure32kOsc configuration
 ******************************************************************************/
/*******************************************************************************
 * Code for BOARD_Configure32kOsc configuration
 ******************************************************************************/
void BOARD_Configure32kOsc(void)
{
    /* Configure 32KHz xtal caps for use with RDM */
    POWER_XTAL32K_ConfigureCaps(OSC_CAP_IN_SETTING, OSC_CAP_OUT_SETTING);
    POWER_PeripheralPowerOn(kPOWERCFG_XTAL32K);
    CLOCK_Select32kOscClkSrc(kCLOCK_Osc32kClockSrc_XTAL);
}